"""Independent literal contract oracle. Usage: python evaluate.py solution.py."""
import argparse
import contextlib
import copy
import hashlib
import importlib.util
import io
import json
from pathlib import Path
import sys


# Expected selections are authored literals, never generated by a second selector.
CASES = [
    ("empty", [], []),
    ("singleton_zero", [{"id": "a", "revision": 0}], [{"id": "a", "revision": 0}]),
    ("highest_not_last", [{"id": "a", "revision": 2}, {"id": "a", "revision": 9}, {"id": "a", "revision": 3}], [{"id": "a", "revision": 9}]),
    ("equal_keeps_first", [{"id": "a", "revision": 2, "tag": "first"}, {"id": "a", "revision": 2, "tag": "second"}], [{"id": "a", "revision": 2, "tag": "first"}]),
    ("tie_after_upgrade", [{"id": "a", "revision": 0}, {"id": "a", "revision": 4, "tag": "first"}, {"id": "a", "revision": 4, "tag": "second"}], [{"id": "a", "revision": 4, "tag": "first"}]),
    ("first_id_order", [{"id": "z", "revision": 1}, {"id": "a", "revision": 5}, {"id": "z", "revision": 7}, {"id": "m", "revision": 0}], [{"id": "z", "revision": 7}, {"id": "a", "revision": 5}, {"id": "m", "revision": 0}]),
    ("invalid_does_not_reserve_order", [{"id": "a", "revision": -1}, {"id": "b", "revision": 0}, {"id": "a", "revision": 2}], [{"id": "b", "revision": 0}, {"id": "a", "revision": 2}]),
    ("missing_keys", [{}, {"id": "a"}, {"revision": 4}, {"id": "b", "revision": 1}], [{"id": "b", "revision": 1}]),
    ("invalid_ids", [{"id": "", "revision": 1}, {"id": None, "revision": 1}, {"id": 1, "revision": 1}, {"id": True, "revision": 1}, {"id": [], "revision": 1}, {"id": {}, "revision": 1}], []),
    ("invalid_revisions", [{"id": "a", "revision": -1}, {"id": "b", "revision": 1.0}, {"id": "c", "revision": "2"}, {"id": "d", "revision": None}, {"id": "e", "revision": []}, {"id": "f", "revision": {}}, {"id": "g", "revision": True}, {"id": "h", "revision": False}], []),
    ("bool_does_not_override", [{"id": "a", "revision": 0, "tag": "valid"}, {"id": "a", "revision": True, "tag": "bad"}], [{"id": "a", "revision": 0, "tag": "valid"}]),
    ("bool_does_not_reserve_order", [{"id": "a", "revision": False}, {"id": "b", "revision": 1}, {"id": "a", "revision": 0}], [{"id": "b", "revision": 1}, {"id": "a", "revision": 0}]),
    ("non_dictionaries", [None, 7, True, "abc", [], ["id", "a"], ("a", 1), {"id": "a", "revision": 1}], [{"id": "a", "revision": 1}]),
    ("whitespace_ids_valid", [{"id": " ", "revision": 0}, {"id": "\t", "revision": 1}, {"id": "\n", "revision": 2}], [{"id": " ", "revision": 0}, {"id": "\t", "revision": 1}, {"id": "\n", "revision": 2}]),
    ("no_id_normalization", [{"id": "a", "revision": 1}, {"id": " a", "revision": 2}, {"id": "a ", "revision": 3}, {"id": "A", "revision": 4}], [{"id": "a", "revision": 1}, {"id": " a", "revision": 2}, {"id": "a ", "revision": 3}, {"id": "A", "revision": 4}]),
    ("unbounded_integer", [{"id": "a", "revision": 18446744073709551616}, {"id": "a", "revision": 18446744073709551615}], [{"id": "a", "revision": 18446744073709551616}]),
    ("extra_keys_nested_preserved", [{"id": "b", "revision": 1, "extra": {"items": [1, 2]}}, {"id": "a", "revision": 0, "other": None}], [{"id": "b", "revision": 1, "extra": {"items": [1, 2]}}, {"id": "a", "revision": 0, "other": None}]),
    ("discarded_records_unchanged", [{"id": "a", "revision": 1, "extra": [1]}, {"id": "a", "revision": 0, "extra": [2]}, {"id": "", "revision": 3, "extra": [3]}], [{"id": "a", "revision": 1, "extra": [1]}]),
]


def evaluate(path):
    sys.dont_write_bytecode = True
    outcomes = []
    load_error = None
    function = None
    try:
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            spec = importlib.util.spec_from_file_location("candidate_solution", path)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            function = module.select_latest
            if not callable(function):
                raise TypeError("select_latest is not callable")
    except BaseException as exc:
        load_error = f"{type(exc).__name__}: {exc}"
    for name, literal_input, expected in CASES:
        records = copy.deepcopy(literal_input)
        before = copy.deepcopy(records)
        original_items = tuple(records)
        error = load_error
        actual = None
        if error is None:
            try:
                with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                    actual = function(records)
            except BaseException as exc:
                error = f"{type(exc).__name__}: {exc}"
        unchanged = records == before and len(records) == len(original_items) and all(a is b for a, b in zip(records, original_items))
        matches = isinstance(actual, list) and actual == expected
        passed = error is None and matches and unchanged
        outcomes.append({"case": name, "passed": passed, "selection_matches": matches, "input_unchanged": unchanged, "error": error})
    passed = sum(case["passed"] for case in outcomes)
    return {"oracle_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(), "solution_sha256": hashlib.sha256(path.read_bytes()).hexdigest(), "total": len(outcomes), "passed": passed, "failed": len(outcomes) - passed, "cases": outcomes}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("solution", type=Path)
    args = parser.parse_args()
    result = evaluate(args.solution.resolve())
    print(json.dumps(result, sort_keys=True))
    return 0 if result["failed"] == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main())
